/*
 *  Everlasting -One-
 *
 *  Let there be n attributes. Each attribute can be Light / Dark.
 *  We are given m special pairs (u, v).
 *
 *  From the original statement, changing jobs allows flipping states under constraints,
 *  and the number of essentially different characters equals:
 *
 *      2^(number of connected components in the graph formed by special pairs)
 *
 *  because inside one connected component, once one attribute's state is fixed,
 *  all others are determined up to a global flip of that component.
 *
 *  Therefore:
 *    - Build an undirected graph on n vertices using the m pairs.
 *    - Count connected components c.
 *    - Answer = 2^c mod 1,000,000,007.
 *
 *  This is the standard interpretation for parity/compatibility constraints on pairs.
 */

public class Main {
    static final long MOD = 1_000_000_007L;

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);

        int n = fs.nextInt();
        int m = fs.nextInt();

        DSU dsu = new DSU(n);

        for (int i = 0; i < m; i++) {
            int a = fs.nextInt() - 1;
            int b = fs.nextInt() - 1;
            dsu.union(a, b);
        }

        int components = 0;
        for (int i = 0; i < n; i++) {
            if (dsu.find(i) == i) components++;
        }

        long ans = modPow(2, components, MOD);
        System.out.println(ans);
    }

    static long modPow(long a, long e, long mod) {
        long r = 1 % mod;
        while (e > 0) {
            if ((e & 1) == 1) r = (r * a) % mod;
            a = (a * a) % mod;
            e >>= 1;
        }
        return r;
    }

    static class DSU {
        int[] p, sz;

        DSU(int n) {
            p = new int[n];
            sz = new int[n];
            for (int i = 0; i < n; i++) {
                p[i] = i;
                sz[i] = 1;
            }
        }

        int find(int x) {
            if (p[x] != x) p[x] = find(p[x]);
            return p[x];
        }

        void union(int a, int b) {
            a = find(a);
            b = find(b);
            if (a == b) return;
            if (sz[a] < sz[b]) {
                int t = a; a = b; b = t;
            }
            p[b] = a;
            sz[a] += sz[b];
        }
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }
}

