#define MOD 1000000007LL

typedef long long ll;

typedef struct {
    int u, v;
} Edge;

static int cmp_int(const void *a, const void *b) {
    int x = *(const int *)a;
    int y = *(const int *)b;
    if (x < y) return -1;
    if (x > y) return 1;
    return 0;
}

static ll mod_pow(ll a, ll e) {
    ll r = 1 % MOD;
    while (e > 0) {
        if (e & 1) r = (r * a) % MOD;
        a = (a * a) % MOD;
        e >>= 1;
    }
    return r;
}

int main(void) {
    int n;
    if (scanf("%d", &n) != 1) return 0;

    Edge *edges = (Edge *)malloc((size_t)n * sizeof(Edge));
    int *vals = (int *)malloc((size_t)(2 * n) * sizeof(int));
    if (!edges || !vals) return 0;

    for (int i = 0; i < n; i++) {
        int a, b;
        scanf("%d %d", &a, &b);
        edges[i].u = a;
        edges[i].v = b;
        vals[2 * i] = a;
        vals[2 * i + 1] = b;
    }

    qsort(vals, 2 * n, sizeof(int), cmp_int);

    int m = 0;
    for (int i = 0; i < 2 * n; i++) {
        if (i == 0 || vals[i] != vals[i - 1]) {
            vals[m++] = vals[i];
        }
    }

    int *deg = (int *)calloc((size_t)m, sizeof(int));
    int *to = (int *)malloc((size_t)(2 * n) * sizeof(int));
    int *next = (int *)malloc((size_t)(2 * n) * sizeof(int));
    int *head = (int *)malloc((size_t)m * sizeof(int));
    int *vis = (int *)calloc((size_t)m, sizeof(int));
    int *queue = (int *)malloc((size_t)m * sizeof(int));
    if (!deg || !to || !next || !head || !vis || !queue) return 0;

    for (int i = 0; i < m; i++) head[i] = -1;

    int ecnt = 0;
    for (int i = 0; i < n; i++) {
        int *pu = (int *)bsearch(&edges[i].u, vals, m, sizeof(int), cmp_int);
        int *pv = (int *)bsearch(&edges[i].v, vals, m, sizeof(int), cmp_int);
        int u = (int)(pu - vals);
        int v = (int)(pv - vals);

        to[ecnt] = v;
        next[ecnt] = head[u];
        head[u] = ecnt++;
        deg[u]++;

        to[ecnt] = u;
        next[ecnt] = head[v];
        head[v] = ecnt++;
        deg[v]++;
    }

    ll ans = 1;

    for (int s = 0; s < m; s++) {
        if (vis[s]) continue;

        int front = 0, back = 0;
        queue[back++] = s;
        vis[s] = 1;

        int vertices = 0;
        ll degsum = 0;

        while (front < back) {
            int u = queue[front++];
            vertices++;
            degsum += deg[u];

            for (int e = head[u]; e != -1; e = next[e]) {
                int v = to[e];
                if (!vis[v]) {
                    vis[v] = 1;
                    queue[back++] = v;
                }
            }
        }

        ll edges_in_comp = degsum / 2;

        if (edges_in_comp == vertices) {
            ans = (ans * 2) % MOD;
        } else {
            ans = (ans * ((mod_pow(2, vertices) - 1 + MOD) % MOD)) % MOD;
        }
    }

    printf("%lld\n", ans % MOD);

    free(edges);
    free(vals);
    free(deg);
    free(to);
    free(next);
    free(head);
    free(vis);
    free(queue);

    return 0;
}

