const int MOD = 1e9 + 7;

struct DSU {
    vector<int> parent, sizeL, sizeD;
    DSU(int n) {
        parent.resize(n);
        sizeL.assign(n, 0);
        sizeD.assign(n, 0);
        for (int i = 0; i < n; i++) parent[i] = i;
    }
    int find(int x) {
        while (parent[x] != x) {
            parent[x] = parent[parent[x]];
            x = parent[x];
        }
        return x;
    }
    void unite(int a, int b) {
        int ra = find(a), rb = find(b);
        if (ra == rb) return;
        if (rand() % 2) swap(ra, rb); 
        parent[ra] = rb;
        sizeL[rb] += sizeL[ra];
        sizeD[rb] += sizeD[ra];
    }
};

int64 modpow(int64 a, int64 b) {
    int64 res = 1;
    while (b > 0) {
        if (b & 1) res = (res * a) % MOD;
        a = (a * a) % MOD;
        b >>= 1;
    }
    return res;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, M;
    cin >> N >> M;

    // We'll map attribute names to indices
    vector<pair<string, string>> pairs(M);
    unordered_map<string, int> idx;
    int nextId = 0;
    for (int i = 0; i < M; i++) {
        cin >> pairs[i].first >> pairs[i].second;
        if (!idx.count(pairs[i].first)) idx[pairs[i].first] = nextId++;
        if (!idx.count(pairs[i].second)) idx[pairs[i].second] = nextId++;
    }

    DSU dsu(nextId);
    // Mark which are light (L) and which are darkness (D)
    for (auto &[a, b] : pairs) {
        int u = idx[a], v = idx[b];
        dsu.unite(u, v);
    }

    // Now we need to know for each component how many L and D it has.
    // We'll first assign types based on first occurrence: 
    // In input, first of pair is L, second is D.
    for (auto &[a, b] : pairs) {
        int u = idx[a], v = idx[b];
        int ru = dsu.find(u), rv = dsu.find(v);
        // They are now in same component after unite, so we just count types at root
    }

    // Actually, we need separate tracking for L and D counts.
    // Reinitialize DSU to track sizes separately.
    DSU dsu2(nextId);
    unordered_map<int, int> lightCount, darkCount;

    for (auto &[a, b] : pairs) {
        int u = idx[a], v = idx[b];
        dsu2.unite(u, v);
    }

    for (auto &[name, id] : idx) {
        int root = dsu2.find(id);
        // We cannot distinguish L/D from names alone, but from pair order:
        // first is L, second is D. So we'll count later.
    }

    // Better: track directly while building DSU.
    DSU dsu3(nextId);
    for (auto &[a, b] : pairs) {
        int u = idx[a], v = idx[b];
        dsu3.unite(u, v);
    }

    // Count L and D for each root
    unordered_map<int, int> cntL, cntD;
    for (auto &[a, b] : pairs) {
        int u = idx[a], v = idx[b];
        int ru = dsu3.find(u);
        int rv = dsu3.find(v);
        cntL[ru]++;  // a is L
        cntD[rv]++;  // b is D
    }

    // But above double-counts if multiple pairs share same attr. 
    // Let's just mark attribute types once.
    unordered_map<int, bool> isLight;
    for (auto &[a, b] : pairs) {
        isLight[idx[a]] = true;  // a is L
        // b is D (so no need to mark, default false)
    }

    DSU dsu4(nextId);
    for (auto &[a, b] : pairs) {
        dsu4.unite(idx[a], idx[b]);
    }

    unordered_map<int, int> compL, compD;
    for (auto &[name, id] : idx) {
        int root = dsu4.find(id);
        if (isLight[id]) compL[root]++;
        else compD[root]++;
    }

    int64 ans = 0;
    for (auto &[root, lc] : compL) {
        int dc = compD[root];
        if (lc > 0 && dc > 0) {
            int64 waysL = (modpow(2, lc) - 1 + MOD) % MOD;
            int64 waysD = (modpow(2, dc) - 1 + MOD) % MOD;
            ans = (ans + waysL * waysD) % MOD;
        }
    }

    cout << ans << "\n";
    return 0;
}

