#include <bits/stdc++.h>
using namespace std;

static const long long MOD = 1000000007LL;

/*
We have 2N attributes: 1..N are "light", N+1..2N are corresponding "dark".
For each i, switching job can replace i <-> i+N.

Given M special pairs (a,b), a character is a subset S of attributes such that:
- no pair in S is incompatible
- if x in S and y is compatible with x, then y may coexist
From the original statement's structure, this becomes:
Build graph on 2N vertices where edges are the given special pairs plus the N opposite-pairs (i, i+N).
Two characters are considered equivalent under repeatedly toggling all attributes in a connected component by job switches.
The count of essentially different characters equals 2^(#connected_components/2) in the transformed bipartite graph.

A simpler and standard interpretation for this problem:
Create DSU on 2N nodes.
Union every given pair (a,b), and also union each attribute with the opposite of the other:
(a^opp, b^opp) due to compatibility under light/dark symmetry.
Finally, for each i, if i and i+N are in same set => contradiction? But statement asks counting different characters, not satisfiability.
The intended known solution is:
- Consider graph on N variables with constraints "same" or "different".
Each pair (a,b) among 2N attributes induces relation between base attributes:
   base(a) and base(b) are same if a,b have same side (both light or both dark),
   different otherwise.
Count connected components in this constraint graph; each bipartite connected component contributes factor 2.
If inconsistent, contributes 0.

Let's implement that.
*/

struct DSU {
    vector<int> p, r;
    DSU(int n = 0) { init(n); }
    void init(int n) {
        p.resize(n);
        r.assign(n, 0);
        iota(p.begin(), p.end(), 0);
    }
    int find(int x) { return p[x] == x ? x : p[x] = find(p[x]); }
    void unite(int a, int b) {
        a = find(a); b = find(b);
        if (a == b) return;
        if (r[a] < r[b]) swap(a, b);
        p[b] = a;
        if (r[a] == r[b]) r[a]++;
    }
};

long long modpow(long long a, long long e) {
    long long r = 1 % MOD;
    while (e) {
        if (e & 1) r = r * a % MOD;
        a = a * a % MOD;
        e >>= 1;
    }
    return r;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, M;
    cin >> N >> M;

    // 2-SAT style DSU on 2*N literals:
    // i : variable i is 0(light), i+N : variable i is 1(dark)
    DSU dsu(2 * N);

    auto id = [&](int x) { return x - 1; };
    auto opp = [&](int v) {
        if (v < N) return v + N;
        return v - N;
    };

    for (int i = 0; i < M; ++i) {
        int a, b;
        cin >> a >> b;
        int x = id(a), y = id(b);

        // Pair means attributes a and b are linked.
        // This induces x == y, and opposite(x) == opposite(y)
        dsu.unite(x, y);
        dsu.unite(opp(x), opp(y));
    }

    // Count components among variables with consistency x != opp(x)
    for (int i = 0; i < N; ++i) {
        if (dsu.find(i) == dsu.find(i + N)) {
            cout << 0 << '\n';
            return 0;
        }
    }

    set<int> reps;
    for (int i = 0; i < 2 * N; ++i) reps.insert(dsu.find(i));

    // Components come in opposite pairs
    long long ans = modpow(2, (long long)reps.size() / 2);
    cout << ans % MOD << '\n';
    return 0;
}
